-[11px] font-semibold text-[#536078]">Provider / bank reference</label><input id="external_reference" name="external_reference" value="{{ old('external_reference') }}" class="mt-2 w-full rounded-xl border border-[#dfe5ec] bg-[#fbfcfe] px-3 py-3 text-sm outline-none focus:border-[#7668f6]" placeholder="Required to approve" /></div><div><label for="review_notes" class="text-[11px] font-semibold text-[#536078]">Review note</label><input id="review_notes" name="review_notes" value="{{ old('review_notes') }}" class="mt-2 w-full rounded-xl border border-[#dfe5ec] bg-[#fbfcfe] px-3 py-3 text-sm outline-none focus:border-[#7668f6]" placeholder="Optional for approval" /></div></div>@if ($errors->any())<div class="rounded-xl border border-[#ffd8cf] bg-[#fff0ec] px-4 py-3 text-xs text-[#b94f3a]">{{ $errors->first() }}</div>@endif<div class="flex flex-wrap gap-3"><button name="decision" value="completed" class="rounded-xl bg-[#36a675] px-4 py-3 text-xs font-semibold text-white">Approve & credit wallet</button><button name="decision" value="rejected" class="rounded-xl bg-[#fff0ec] px-4 py-3 text-xs font-semibold text-[#b94f3a]">Reject deposit</button></div><p class="text-[11px] leading-5 text-[#9aa5b7]">Approval posts a balanced ledger entry and cannot be undone by editing. Reversals must be separate compensating entries.</p></form>@else<div class="p-6 text-xs text-[#7b879a] sm:p-8">This deposit is no longer awaiting review. Settlement reference: <span class="font-mono text-[#0a1324]">{{ $deposit->external_reference ?? '—' }}</span></div>@endif</section></div>
